(()=>{const board=document.querySelector('.problem-analysis');if(!board)return;const frame=document.createElement('div');frame.className='problem-fit';board.before(frame);frame.append(board);const mq=matchMedia('(max-width:1279px)');function fit(){if(!mq.matches){frame.style.height='';board.style.removeProperty('--problem-scale');return}const scale=Math.min(1,frame.clientWidth/board.offsetWidth);board.style.setProperty('--problem-scale',scale);frame.style.height=Math.ceil(board.offsetHeight*scale)+'px'}new ResizeObserver(fit).observe(frame);addEventListener('resize',fit,{passive:true});document.fonts.ready.then(fit);fit()})();